mapper.select:
SELECT t.date, IFNULL(t1.bool_exists, 0) AS bool_exists_unapproved_data FROM (
select #{date} AS date
) t LEFT JOIN ( SELECT st.in_year_month_day_date, COUNT(1) > 0 AS bool_exists FROM ( SELECT mbptr.id, mbptr.in_year_month_day_date, mbptr.in_year_month_date, mbptr.workshop_id, mbptr.task_type_enum FROM mes_building_produce_team_report mbptr WHERE mbptr.bool_delete_enum = 0 AND mbptr.in_year_month_date = DATE_FORMAT(#{yearMonth}, '%Y-%m') AND mbptr.inspection_quantity > 0 AND NOT EXISTS( SELECT 1 FROM mes_production_reporting_approval_passed_produce_team_report mprapptrl WHERE mprapptrl.bool_delete_enum = 0 AND mprapptrl.product_type_enum != ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND mprapptrl.produce_team_report_id = mbptr.id ) UNION ALL SELECT meptr.id, DATE(meptr.create_time) AS in_year_month_day_date, DATE_FORMAT(meptr.create_time, '%Y-%m') AS in_year_month_date, meptr.workshop_id, ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AS task_type_enum FROM mes_enclosure_produce_team_report meptr WHERE meptr.bool_delete_enum = 0 AND DATE_FORMAT(meptr.create_time, '%Y-%m') = DATE_FORMAT(#{yearMonth}, '%Y-%m') AND meptr.quantity > 0 AND NOT EXISTS( SELECT 1 FROM mes_production_reporting_approval_passed_produce_team_report mprapptrl WHERE mprapptrl.bool_delete_enum = 0 AND mprapptrl.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND mprapptrl.produce_team_report_id = meptr.id ) ) st
AND st.workshop_id = #{workshopId}
AND st.task_type_enum = #{productTypeEnum}
GROUP BY st.in_year_month_day_date ) t1 ON t1.in_year_month_day_date = t.date ORDER BY t.date

SELECT t.date, IFNULL(t1.bool_exists, 0) AS bool_exists_approved_data FROM (
select #{date} AS date
) t LEFT JOIN ( SELECT DATE(mprap.approval_date) AS year_month_day, COUNT(1) > 0 AS bool_exists FROM mes_production_reporting_approval_passed mprap WHERE mprap.bool_delete_enum = 0 AND DATE_FORMAT(mprap.approval_date, '%Y-%m') = DATE_FORMAT(#{yearMonth}, '%Y-%m')
AND mprap.workshop_id = #{workshopId}
AND mprap.product_type_enum = #{productTypeEnum}
GROUP BY DATE(mprap.approval_date) ) t1 ON t1.year_month_day = t.date

SELECT t.product_type_enum, t.report_quantity, mbw.id AS 'workshop.id', mbw.name AS 'workshop.name', mbp.id AS 'process.id', mbp.name AS 'process.name', mbp.type AS 'process.type', mbtul.team_id AS 'team.id', mbtul.user_name AS 'team.name' FROM ( SELECT mbptr.workshop_id, mbptr.process_id, mbptr.task_type_enum AS product_type_enum, mbptr.team_id, SUM(mbptr.inspection_quantity) AS report_quantity FROM ( SELECT s1.id, s1.in_year_month_day_date, s1.in_year_month_date, s1.workshop_id, s1.task_type_enum, s1.team_id, s1.process_id, s1.inspection_quantity FROM mes_building_produce_team_report s1 WHERE s1.bool_delete_enum = 0 AND s1.inspection_quantity > 0 AND NOT EXISTS( SELECT 1 FROM mes_production_reporting_approval_passed_produce_team_report mprapptrl WHERE mprapptrl.bool_delete_enum = 0 AND mprapptrl.product_type_enum != ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND mprapptrl.produce_team_report_id = s1.id ) UNION ALL SELECT s2.id, DATE(s2.create_time) AS in_year_month_day_date, DATE_FORMAT(s2.create_time, '%Y-%m') AS in_year_month_date, s2.workshop_id, ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AS task_type_enum, s2.team_id, s2.process_id, s2.quantity FROM mes_enclosure_produce_team_report s2 WHERE s2.bool_delete_enum = 0 AND s2.quantity > 0 AND NOT EXISTS( SELECT 1 FROM mes_production_reporting_approval_passed_produce_team_report mprapptrl WHERE mprapptrl.bool_delete_enum = 0 AND mprapptrl.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND mprapptrl.produce_team_report_id = s2.id ) ) mbptr WHERE mbptr.in_year_month_day_date = #{date}
AND mbptr.workshop_id = #{workshopId}
AND mbptr.task_type_enum = #{productTypeEnum}
GROUP BY mbptr.workshop_id, mbptr.process_id, mbptr.task_type_enum, mbptr.team_id ) t LEFT JOIN mes_building_workshop mbw ON mbw.bool_delete_enum = 0 AND mbw.id = t.workshop_id LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = t.process_id LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = t.team_id

SELECT t.product_type_enum, t.report_quantity, mbw.id AS 'workshop.id', mbw.name AS 'workshop.name', mbp.id AS 'process.id', mbp.name AS 'process.name', mbtul.team_id AS 'team.id', mbtul.user_name AS 'team.name' FROM ( SELECT mprap.workshop_id, mprap.process_id, mprap.product_type_enum, mprap.team_id, SUM(mprap.report_quantity) AS report_quantity FROM mes_production_reporting_approval_passed mprap WHERE mprap.bool_delete_enum = 0 AND DATE(mprap.approval_date) = #{date}
AND mprap.workshop_id = #{workshopId}
AND mprap.product_type_enum = #{productTypeEnum}
GROUP BY mprap.workshop_id, mprap.process_id, mprap.product_type_enum, mprap.team_id ) t LEFT JOIN mes_building_workshop mbw ON mbw.bool_delete_enum = 0 AND mbw.id = t.workshop_id LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = t.process_id LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = t.team_id

SELECT t.produce_team_report_ids, t.report_date, p.id AS 'project.id', p.name AS 'project.name', p.serial_number AS 'project.serial_number', p.short_name AS 'project.short_name', workshop.id AS 'workshop.id', workshop.name AS 'workshop.name', process.id AS 'process.id', process.name AS 'process.name', process.type AS 'process.type', team.id AS 'team.id', team.name AS 'team.name', team.organization_type AS 'team.organization_type', dict.id AS 'dict.id', dict.label AS 'dict.label', t.serial_numbers AS product_serial_numbers, t.report_quantity, mqce.unit AS measure_unit, if(mqce.unit IS NOT NULL, t.measurement_quantity, NULL) AS measurement_quantity, mqce.price, (t.measurement_quantity * mqce.price) AS amount, mqce.id AS quota_config_id, mqce.serial_number AS quota_config_serial_number, #{productTypeEnum} AS 'product.product_type_enum', user.id AS 'reportPerson.id', user.name AS 'reportPerson.name' FROM ( SELECT group_concat(DISTINCT meptr.id) AS produce_team_report_ids, DATE(meptr.create_time) AS report_date, meptr.workshop_id, meptr.process_id, meptr.team_id, meptr.project_id, product.dictionary_id, meptr.user_id, sum(meptr.quantity) AS report_quantity, sum(product.length / 1000) AS measurement_quantity, group_concat(DISTINCT product.serial_number) AS serial_numbers FROM mes_enclosure_produce_team_report meptr LEFT JOIN tech_enclosure product ON product.bool_delete_enum = 0 AND product.id = meptr.product_id WHERE meptr.bool_delete_enum = 0 AND DATE(meptr.create_time) = #{date} AND NOT EXISTS( SELECT 1 FROM mes_production_reporting_approval_passed_produce_team_report mprapptrl WHERE mprapptrl.bool_delete_enum = 0 AND mprapptrl.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND mprapptrl.produce_team_report_id = meptr.id ) AND meptr.workshop_id = #{workshopId} AND ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} = #{productTypeEnum} AND meptr.process_id = #{processId} AND meptr.team_id = #{teamId}
AND meptr.project_id = #{projectId}
GROUP BY DATE(meptr.create_time), meptr.workshop_id, meptr.process_id, meptr.team_id, meptr.project_id, product.dictionary_id, meptr.user_id ) t LEFT JOIN sys_dictionary dict ON dict.bool_delete_enum = 0 AND dict.id = t.dictionary_id LEFT JOIN mes_quota_config_enclosure mqce ON mqce.bool_delete_enum = 0 AND mqce.enclosure_type_dictionary_id = t.dictionary_id LEFT JOIN contract_project p ON p.bool_delete_enum = 0 AND p.id = t.project_id LEFT JOIN mes_building_workshop workshop on workshop.bool_delete_enum = 0 and workshop.id = t.workshop_id LEFT JOIN mes_building_process process on process.bool_delete_enum = 0 and process.id = t.process_id LEFT JOIN ( SELECT mbt.*, mbtul.user_name AS name FROM mes_building_team mbt LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = mbt.id WHERE mbt.bool_delete_enum = 0 ) team ON team.id = t.team_id LEFT JOIN sys_user user ON user.bool_delete_enum = 0 AND user.id = t.user_id

SELECT t.*, '吨' AS unit, workshop.id AS 'workshop.id', workshop.name AS 'workshop.name', team.id AS 'team.id', team.name AS 'team.name' FROM ( SELECT mprap.workshop_id, mprap.team_id, SUM(ROUND((mprap.report_quantity * CASE mprap.product_type_enum WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} THEN artifact.net_weight WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} THEN assemble.net_weight WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} THEN machinePart.net_weight END) / 1000, 6)) AS production_volume, sum(mprap.amount) AS total_salary FROM mes_production_reporting_approval_passed mprap LEFT JOIN tech_artifact artifact ON artifact.bool_delete_enum = 0 AND artifact.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} LEFT JOIN tech_assemble assemble ON assemble.bool_delete_enum = 0 AND assemble.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} LEFT JOIN tech_machine_part machinePart ON machinePart.bool_delete_enum = 0 AND machinePart.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} WHERE mprap.bool_delete_enum = 0
AND mprap.workshop_id = #{workshopId}
AND mprap.team_id = #{teamId}
AND mprap.process_id = #{processId}
AND DATE(mprap.report_date) >= #{startDate}
AND DATE(mprap.report_date) <= #{endDate}
GROUP BY mprap.workshop_id, mprap.team_id ) t LEFT JOIN mes_building_workshop workshop ON workshop.bool_delete_enum = 0 AND workshop.id = t.workshop_id LEFT JOIN ( SELECT mbt.*, mbtul.user_name AS name FROM mes_building_team mbt LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = mbt.id WHERE mbt.bool_delete_enum = 0 ) team ON team.id = t.team_id

SELECT t.*, '米' AS unit, workshop.id AS 'workshop.id', workshop.name AS 'workshop.name', team.id AS 'team.id', team.name AS 'team.name' FROM ( SELECT mprap.workshop_id, mprap.team_id, SUM(ROUND((mprap.report_quantity * enclosure.length) / 1000, 6)) AS production_volume, sum(mprap.amount) AS total_salary FROM mes_production_reporting_approval_passed mprap LEFT JOIN tech_enclosure enclosure ON enclosure.bool_delete_enum = 0 AND enclosure.id = mprap.product_id WHERE mprap.bool_delete_enum = 0 AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
AND mprap.workshop_id = #{workshopId}
AND mprap.team_id = #{teamId}
AND mprap.process_id = #{processId}
AND DATE(mprap.report_date) >= #{startDate}
AND DATE(mprap.report_date) <= #{endDate}
GROUP BY mprap.workshop_id, mprap.team_id ) t LEFT JOIN mes_building_workshop workshop ON workshop.bool_delete_enum = 0 AND workshop.id = t.workshop_id LEFT JOIN ( SELECT mbt.*, mbtul.user_name AS name FROM mes_building_team mbt LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = mbt.id WHERE mbt.bool_delete_enum = 0 ) team ON team.id = t.team_id

SELECT t.*, areaBatch.id AS 'areaBatch.id', areaBatch.name AS 'areaBatch.name' FROM ( SELECT mprap.id, project.id AS 'project.id', project.name AS 'project.name', project.serial_number AS 'project.serial_number', project.short_name AS 'project.short_name', mprap.product_id AS 'product.id', CASE mprap.product_type_enum WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} THEN artifact.serial_number WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} THEN assemble.serial_number WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} THEN machinePart.serial_number WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} THEN enclosure.serial_number END AS 'product.serial_number', CASE mprap.product_type_enum WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} THEN artifact.specification WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} THEN assemble.specification WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} THEN machinePart.specification WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} THEN enclosure.plate END AS 'product.specification', CASE mprap.product_type_enum WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} THEN artifact.area_batch_id WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} THEN assemble.area_batch_id WHEN ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} THEN machinePart.area_batch_id END AS area_batch_id, process.id AS 'process.id', process.name AS 'process.name', mprap.quota_config_id, mprap.quota_config_serial_number, mprap.measure_unit, mprap.measurement_quantity, mprap.price, mprap.amount, mprap.report_date, approver.id AS 'approver.id', approver.name AS 'approver.name', mprap.approval_date, reportPerson.id AS 'reportPerson.id', reportPerson.name AS 'reportPerson.name' FROM mes_production_reporting_approval_passed mprap LEFT JOIN contract_project project ON project.bool_delete_enum = 0 AND project.id = mprap.project_id LEFT JOIN mes_building_process process ON process.bool_delete_enum = 0 AND process.id = mprap.process_id LEFT JOIN sys_user approver ON approver.bool_delete_enum = 0 AND approver.id = mprap.approver_id LEFT JOIN tech_artifact artifact ON artifact.bool_delete_enum = 0 AND artifact.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} LEFT JOIN tech_assemble assemble ON assemble.bool_delete_enum = 0 AND assemble.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()} LEFT JOIN tech_machine_part machinePart ON machinePart.bool_delete_enum = 0 AND machinePart.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} LEFT JOIN tech_enclosure enclosure ON enclosure.bool_delete_enum = 0 AND enclosure.id = mprap.product_id AND mprap.product_type_enum = ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} LEFT JOIN sys_user reportPerson ON reportPerson.bool_delete_enum = 0 AND reportPerson.id = mprap.report_person_id WHERE mprap.bool_delete_enum = 0 AND mprap.workshop_id = #{workshopId} AND mprap.team_id = #{teamId}
AND DATE(mprap.report_date) >= #{startDate}
AND DATE(mprap.report_date) <= #{endDate}
) t LEFT JOIN plan_area_batch areaBatch ON areaBatch.bool_delete_enum = 0 and areaBatch.id = t.area_batch_id
AND t.`product.serial_number` LIKE concat('%', #{productSerialNumber}, '%')

SELECT
product.id AS 'product.id', product.serial_number AS 'product.serial_number',
project.id AS 'project.id', project.name AS 'project.name', team.id AS 'team.id', team.name AS 'team.name', team.organization_type AS 'team.organization_type', mprap.* FROM mes_production_reporting_approval_passed mprap LEFT JOIN contract_project project ON project.bool_delete_enum = 0 AND project.id = mprap.project_id LEFT JOIN ( SELECT mbt.*, mbtul.user_name AS name FROM mes_building_team mbt LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = mbt.id WHERE mbt.bool_delete_enum = 0 ) team ON team.id = mprap.team_id
LEFT JOIN tech_artifact product ON product.bool_delete_enum = 0 AND product.id = mprap.product_id
LEFT JOIN tech_assemble product ON product.bool_delete_enum = 0 AND product.id = mprap.product_id
LEFT JOIN tech_machine_part product ON product.bool_delete_enum = 0 AND product.id = mprap.product_id
LEFT JOIN tech_enclosure product ON product.bool_delete_enum = 0 AND product.id = mprap.product_id
WHERE mprap.bool_delete_enum = 0
AND mprap.project_id = #{projectId}
AND mprap.monomer_id = #{monomerId}
AND mprap.product_type_enum = #{productTypeEnum}
AND product.serial_number
#{i}
